import{_ as s,C as i,c as l,o as p,a3 as a,G as n,j as r,a as o}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Departments","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/departments/departments.md","filePath":"master/human-resources/employees/departments/departments.md","lastUpdated":1791902625000}'),m={name:"master/human-resources/employees/departments/departments.md"};function h(d,e,g,c,u,y){const t=i("ImagePopup");return p(),l("div",null,[e[0]||(e[0]=a('<h1 id="departments" tabindex="-1">Departments <a class="header-anchor" href="#departments" aria-label="Permalink to &quot;Departments&quot;">​</a></h1><p>A department is a part of your company, such as Sales or Operations. You give each employee a department so you can see who works where. A department can sit inside another one, for example Quality Check Department inside Research &amp; Development. It can also have a manager.</p><blockquote><p><strong>In simple words:</strong> A department is a team box that holds employees, with an optional boss and an optional parent box.</p></blockquote><p>Open <code>Employees → Departments</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>The <strong>Manager</strong> is an existing employee, so create that person first. See <a href="./../employees/add-employee.html">Add an employee</a>. The company must also exist. See <a href="./../../../general-settings/companies/companies.html">Companies</a>.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page shows departments as cards, not as a table. Each card shows the manager&#39;s picture and name (if one is set), the department name and the company.</p>',7)),n(t,{src:"/images1/employees/dep_list_cards.png",alt:"Departments page showing department cards with a checkbox on each card and the Default and Archived Departments tabs"}),e[1]||(e[1]=a('<ul><li><strong>Default:</strong> departments in use.</li><li><strong>Archived Departments:</strong> departments you deleted. You can restore them from here. The tab is empty (<strong>No departments</strong>) until you archive one.</li><li><strong>Search:</strong> type a name to narrow the cards.</li><li><strong>Sort by:</strong> order the cards by <strong>Name</strong> or <strong>Manager</strong>.</li><li><strong>Group by:</strong> group cards by <strong>Name</strong>, <strong>Company</strong>, <strong>Manager</strong>, <strong>Created At</strong> or <strong>Updated At</strong>.</li><li><strong>Filter:</strong> build rules on <strong>Name</strong>, <strong>Manager</strong>, <strong>Company</strong>, <strong>Created At</strong> or <strong>Updated At</strong>.</li></ul><p>Each card has a checkbox and <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong> links.</p><h2 id="create-a-department" tabindex="-1">Create a department <a class="header-anchor" href="#create-a-department" aria-label="Permalink to &quot;Create a department&quot;">​</a></h2><p>This example creates the <strong>Operations</strong> department, managed by Sarah Mitchell. If it already exists in your data, nothing else changes when you follow the steps.</p><ol><li>Open <code>Employees → Departments</code>.</li><li>Click <strong>New Department</strong>. A full page opens.</li></ol>',5)),n(t,{src:"/images1/employees/dep_new_button.png",alt:"Departments page with the New Department button highlighted"}),e[2]||(e[2]=a('<ol start="3"><li>Fill in the <strong>General Information</strong> section.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Type <code>Operations</code>.</li><li><strong><em>Parent Department:</em></strong> Optional. Pick the department that contains this one. Leave it empty for a top level department.</li><li><strong><em>Manager:</em></strong> Optional. Pick <strong>Sarah Mitchell</strong>.</li><li><strong><em>Company:</em></strong> Fills with your company. Change it only if you run several companies.</li><li><strong><em>Color:</em></strong> Optional. Leave it blank for Operations. Pick a colour from the circle picker. It is blank by default. A colour marks the department in the organization tree. The card does not show it.</li></ul>',2)),n(t,{src:"/images1/employees/dep_create_form.png",alt:"Create Department form titled General Information, filled with Operations as name and Sarah Mitchell as manager, with Create, Create & create another and Cancel"}),e[3]||(e[3]=a('<ol start="4"><li>Click <strong>Create</strong>. The other buttons are <strong>Create &amp; create another</strong> and <strong>Cancel</strong>. A <strong>Department created</strong> notification says <strong>The department has been created successfully.</strong> Aureus opens the new department.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Click <strong>Create &amp; create another</strong> to add several departments in a row.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you change <strong>Company</strong>, Aureus clears <strong>Parent Department</strong> and <strong>Manager</strong> when they belong to another company. Pick them again. The lists only show records of the chosen company.</p></div><h2 id="the-department-page" tabindex="-1">The department page <a class="header-anchor" href="#the-department-page" aria-label="Permalink to &quot;The department page&quot;">​</a></h2><p>Click <strong>View</strong> on a card. Three tabs sit at the top: <strong>View</strong>, <strong>Edit</strong> and <strong>Manage Employees</strong>.</p><p>The <strong>View</strong> tab shows a <strong>General</strong> section with <strong>Name</strong>, <strong>Manager</strong>, <strong>Company</strong> and <strong>Color</strong>. An empty manager shows a dash. The header has a <strong>Delete</strong> button and a chat-comments button.</p>',6)),n(t,{src:"/images1/employees/dep_view_operations.png",alt:"View tab of the Operations department with the General section (name, manager, company and an orange colour swatch), the Delete button and the chat-comments button in the header"}),e[4]||(e[4]=r("h3",{id:"department-organization",tabindex:"-1"},[o("Department Organization "),r("a",{class:"header-anchor",href:"#department-organization","aria-label":'Permalink to "Department Organization"'},"​")],-1)),e[5]||(e[5]=r("p",null,[o("This tree is headed "),r("strong",null,"Department Organization"),o(" with the sub-heading "),r("strong",null,"Hierarchy"),o(". It appears only when the department has a parent. It lists the departments from the top one down. Each line shows the name and a member count. The manager follows the name when one is set. The current department is bold, and red when its colour is red.")],-1)),e[6]||(e[6]=r("p",null,"For example, Quality Check Department sits under Research & Development. Its page shows Research & Development (2 members) first, then Quality Check Department (0 members) indented below it. Quality Check Department has a red colour.",-1)),n(t,{src:"/images1/employees/dep_view_tree.png",alt:"Department Organization tree showing Research & Development with Quality Check Department below it"}),e[7]||(e[7]=a('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>Treat the member counts as a hint only. They may not match the list on the <strong>Manage Employees</strong> tab. A top level department such as Operations shows no tree.</p></div><h2 id="manage-the-employees-of-a-department" tabindex="-1">Manage the employees of a department <a class="header-anchor" href="#manage-the-employees-of-a-department" aria-label="Permalink to &quot;Manage the employees of a department&quot;">​</a></h2><p>Open the <strong>Manage Employees</strong> tab. It lists the people in this department as cards. Each card shows the name, job title, work email, work phone and badges.</p><ol><li>Open the <strong>Operations</strong> department.</li><li>Click <strong>Manage Employees</strong>.</li><li>Click <strong>New Employee</strong> to add someone straight into this department.</li></ol>',4)),n(t,{src:"/images1/employees/dep_manage_employees.png",alt:"Manage Employees tab of a department with the New Employee button and employee cards"}),e[8]||(e[8]=a('<p>Use <strong>Group by</strong>, <strong>Sort by</strong> and search here as you do on the main employee list. See <a href="./../employees/employee-list.html">Employee list</a>.</p><h2 id="edit-archive-and-restore" tabindex="-1">Edit, archive and restore <a class="header-anchor" href="#edit-archive-and-restore" aria-label="Permalink to &quot;Edit, archive and restore&quot;">​</a></h2><p>Click <strong>Edit</strong> on a card, or open the <strong>Edit</strong> tab. The form is the same as for creating. Click <strong>Save changes</strong> to keep your edits.</p><p>Click <strong>Delete</strong> to archive a department. It moves to <strong>Archived Departments</strong>. There, use <strong>Restore</strong> to bring it back.</p><h2 id="chatter" tabindex="-1">Chatter <a class="header-anchor" href="#chatter" aria-label="Permalink to &quot;Chatter&quot;">​</a></h2><p>The department page has a <strong>Chatter</strong> button. Use it to send messages and log notes about the department. See <a href="./../../../getting-started/chatter.html">Chatter</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../employees/add-employee.html">Add an employee</a></li><li><a href="./../setup/job-positions.html">Job positions</a></li><li><a href="./../setup/activity-plans.html">Activity plans</a></li></ul>',8))])}const f=s(m,[["render",h]]);export{_ as __pageData,f as default};
